"""Build a focused, self-contained technology report and the research log."""
from pathlib import Path
import base64
import html
import json
import hashlib
import re
import pandas as pd

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/"outputs"
TABLE=OUT/"tables"
def read(name):return pd.read_csv(TABLE/(name+".csv"))
def pct(x):return f"{100*x:.1f}%"

class Report:
    def __init__(self):self.md=[];self.web=[]
    def heading(self,title,level=2):self.md.append("#"*level+" "+title);self.web.append(f"<h{level}>{html.escape(title)}</h{level}>")
    def inline(self,text):
        text=html.escape(text)
        text=re.sub(r"\*\*(.*?)\*\*",r"<strong>\1</strong>",text)
        text=re.sub(r"\[([^\]]+)\]\((https?://[^)]+)\)",r'<a href="\2">\1</a>',text)
        return text
    def para(self,text):self.md.append(text);self.web.append("<p>"+self.inline(text)+"</p>")
    def table(self,d):
        rows=[[str(x).replace("|","/") for x in row] for row in d.itertuples(index=False,name=None)]
        self.md.append("| "+" | ".join(map(str,d.columns))+" |\n| "+" | ".join(["---"]*len(d.columns))+" |\n"+"\n".join("| "+" | ".join(row)+" |" for row in rows))
        self.web.append('<div class="table">'+d.to_html(index=False,escape=True,border=0)+'</div>')
    def bullets(self,items):self.md.append("\n".join("- "+x for x in items));self.web.append("<ul>"+"".join("<li>"+self.inline(x)+"</li>" for x in items)+"</ul>")
    def figure(self,name):
        p=OUT/"figures"/(name+".png")
        self.md.append(f"![{name.replace('_',' ')}](figures/{name}.png)")
        b=base64.b64encode(p.read_bytes()).decode()
        self.web.append(f'<figure><img alt="{html.escape(name)}" src="data:image/png;base64,{b}"></figure>')
    def write(self,name):
        (OUT/(name+".md")).write_text("\n\n".join(self.md)+"\n")
        css="""body{margin:0;color:#263c46;background:#f3f6f7;font-family:Arial,sans-serif;line-height:1.6}main{max-width:1050px;margin:35px auto;padding:48px;background:white}h1{font-size:32px;line-height:1.2}h2{font-size:24px;margin-top:44px;border-top:1px solid #d3dfe3;padding-top:24px}h3{font-size:18px}p,li{font-size:15px}a{color:#17667b}table{width:100%;border-collapse:collapse;font-size:13px}th{text-align:left;background:#e5eff2}th,td{padding:9px 11px;border-bottom:1px solid #d3dfe3}figure{margin:25px 0}img{width:100%;height:auto}.table{overflow-x:auto}footer{font-size:12px;color:#64747e;margin-top:45px}@media(max-width:700px){main{padding:22px;margin:0}h1{font-size:25px}}@media print{body{background:white}main{margin:0;padding:0}figure,table{break-inside:avoid}h2{break-after:avoid}}"""
        doc='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AI patent technology extension</title><style>'+css+'</style></head><body><main>'+"\n".join(self.web)+'<footer>Independent exploratory analysis · 4 October 2026 · Original dataset preserved</footer></main></body></html>'
        (OUT/(name+".html")).write_text(doc)

def research_log(summary):
    entries=[]
    def entry(observation,hypothesis,decision,justification,result,limitation,alternatives):
        entries.append(dict(observation=observation,hypothesis=hypothesis,decision=decision,justification=justification,result=result,limitation=limitation,reasonable_alternatives=alternatives))
    entry("The preceding analysis found Qualcomm denominator expansion and NVIDIA ML growth.","Technology composition can distinguish substantive portfolio changes from label-only changes.","Enrich Qualcomm 2021/2023 and NVIDIA 2014–2016/2021–2023 grants.","These directly match the two findings requested for investigation; NVIDIA windows have equal three-year duration.","7,813 supplied grant rows selected; 263,602 source rows outside the extension scope, not deleted from the original analysis.","This extension cannot locate the precise transition year between NVIDIA windows.","Enrich every company/year; use intermediate years; use a probability sample.")
    entry("Official USPTO PatentsView bulk metadata was downloadable.","A census avoids convenience-sample bias.","Download fixed December 2024 release and verify published MD5s; retain all target titles, abstracts and dates.","Public bulk inputs are reproducible and remove the need for random sampling.","All 7,813 target grants have title, abstract and filing-date fields.","Titles/abstracts are not a full reading of claims or specifications.","Stratified random sampling; Google Patents search exports; licensed commercial metadata.")
    entry("CPC is one-to-many and evolves over time.","Reclassification may create apparent technology changes.","Use current codes from one snapshot; retain at-issue codes for sensitivity.","A common snapshot improves comparability without pretending classification history is stable.","Current and at-issue interpretations broadly agree; paired NVIDIA check uses 742 early and 784 recent grants.","At-issue codes absent for 267 early NVIDIA grants; three further grants excluded only from paired sensitivity because current codes absent.","At-issue-only analysis; IPC concordance; historical CPC scheme crosswalk.")
    entry("Communications codes overlap across subclasses.","A simple membership partition can identify where the net non-AI increase lies.","Define communications-associated as any H04W/L/B/J/K/M code; each grant counted once in the partition.","The partition is exact, interpretable and does not sum overlapping subclass totals.","Communications-associated increase 1,608 / total classifier-negative increase 1,617 = 99.4%.","Association with communications is not an exclusive invention field or proof of a causal reason.","First-listed CPC; fractional subclass credit (also supplied); detailed CPC groups.")
    entry("Current CPC omits six reissues.","Code absence is a metadata limitation, not an invalid patent.","Retain reissues, blank codes and a no-communications/no-current-code category.","Deleting unusual identifiers would miscount genuine grants.","No patent rows removed; six missing current-CPC cases exported for review.","A missing code must not be interpreted as absence of that technology.","Exclude reissues with explicit sensitivity; retrieve original-patent codes.")
    entry("Classifier-negative is operational, not biological/technical truth.","Qualcomm composition accounting may depend on the AI cutoff.","Repeat the decomposition at 50, 86 and 93; repeat with inventional codes only.","This probes label and coding choices without selecting a cutoff for significance.","Communications explain 98.6%–99.7% of the net negative-grant increase across 12 specifications.","Threshold sensitivity does not validate AIPD recall or precision.","Human claim-based labels; probabilistic score weighting.")
    entry("Text phrases identify concrete themes but abstracts contain boilerplate.","Specific technical terms, corroborated by CPC and title-only checks, are more useful than raw topic ranks.","Use disclosed regex phrase rules and separate exploratory bigram contrasts; no opaque topic model.","Raw phrase rankings include drafting phrases such as 'various examples', which are not technologies.","Sidelink, learned methods and autonomy increase in both title-only and combined-text analyses.","Rules are exploratory and may miss synonyms or mention background technologies.","NMF/LDA after boilerplate removal; embeddings with manual validation; blinded human coding.")
    entry("Ray-tracing and rendering have orthographic/stem variants.","Exact wording choices can affect counts.","Match ray-tracing/ray tracing/raytracing stems and render*; freeze rules in text_rules.json.","These are reasonable spelling and morphology variants, chosen before the final tables rather than for significance.","Ray-tracing matches 5→60; rendering 118→106; 56 of 60 recent ray-tracing grants are ML86-negative.","A keyword does not prove the patented claim's principal technical contribution.","Exact-phrase counts; manual classification of graphics claims.")
    entry("Qualcomm grant dates are later than the activity described in filings.","Expansion may be driven by prior filing cohorts or prosecution delays.","Add direct filing dates and grant lags; preserve unusual durations.","Timing is needed before attributing 2023 grants to 2023 innovation or strategy.","2,916 / 3,446 negative 2023 grants were filed in 2020–2021; lag median 2.12→2.30 years, mean almost unchanged.","Only granted applications are observed; direct filing dates need not equal first priority.","All pre-grant filings; allowance/prosecution histories; earliest family priorities.")
    entry("NVIDIA ML-positive and non-ML counts both change.","Share growth can reflect more positives and fewer negatives.","Use two-factor Shapley accounting, averaging both update orders.","Contributions add exactly and avoid choosing an arbitrary ordering.",summary["accounting_result"],"Accounting contributions are not causal treatment effects.","One-order counterfactual; log-odds decomposition; Kitagawa decomposition.")
    entry("Neural and vision/control evidence overlap in NVIDIA ML grants.","An additive partition can describe most of the ML rise without double-counting.","Order explicit learning text, then vision/control evidence without such text, then remaining ML grants.","The hierarchy makes the accounting transparent; retain independent overlapping theme counts as well.","Explicit learning category 0→177, vision/control without explicit learning 1→38, other 6→15; total 7→230.","Category order changes attribution; 'vision/control' combines image/vision CPC, perception phrases and autonomous mentions.","Nonexclusive thematic prevalence; fractional multi-theme allocation.")
    entry("G06V recognition classifications were revised with transfers from G06K9.","An isolated G06V trend can confuse scheme change with innovation.","Check a harmonized G06T/G06V/G06K9 union and paired current/issue records.","Official CPC revision notice documents reclassification; text corroboration is independent of code migration.","Paired vision/pattern share increases 29.5%→50.0% current and 28.3%→48.9% at issue.","This is a pragmatic union, not a complete historical CPC concordance.","Detailed revision crosswalk; IPC; exclude G06V and rely on text.")
    entry("The targeted rows are a finite census, selected after the preceding EDA.","Population-style patent-independent p-values or confidence intervals would impose unsupported assumptions.","Use exact finite-cohort effects, threshold/snapshot checks and leave-one-quarter-out ranges; no new confirmatory tests.","Unknown patent families and a one-year Qualcomm cohort make conventional inference unjustified.","Sidelink share change remains +9.68 to +10.67 pp; NVIDIA explicit-learning change +23.11 to +24.45 pp under quarter omission.","Sensitivity ranges are not confidence intervals; these results do not generalize to unobserved inventions.","Family-clustered inference after family linkage; prespecified replication period; temporal bootstrap with validated assumptions.")
    entry("Ten recent NVIDIA grants explicitly mention learned methods but fall below ML86.","Some disagreement reflects component boundaries, text scope or model error.","Export all ten; inspect a linked accelerator case using original patent pages.","Anomalies inform interpretation and should not be deleted or automatically relabeled.","Nine remain any-AI86-positive. Three linked same-title accelerator grants have ML scores 0.000484, 0.999996, 0.003449; all hardware86-positive.","This does not establish a specific classifier error mechanism; claims differ and same-title patents can be distinct.","Expert claims adjudication; full AIPD inference-input audit; broader family study.")
    (OUT/"research_log.jsonl").write_text("\n".join(json.dumps(x,ensure_ascii=False) for x in entries)+"\n")
    text=["# Research log — CPC/text extension"]
    for i,x in enumerate(entries,1):
        text.append(f"## Decision {i}")
        for k,v in x.items():text.append(f"**{k.replace('_',' ').capitalize()}:** {v}")
    (OUT/"research_log.md").write_text("\n\n".join(text)+"\n")

if __name__=="__main__":
    expected="f4fdc65071bfba1448107e9ac63d25d56f0ab996fd3b38ffd2d897dc55beb256"
